def header():
    links = ''.join(f'<a href="{href}">{label}</a>' for label, href in NAV)
    return f'''<header class="site-header"><div class="wrap nav"><a class="brand" href="index.html"><img src="assets/brand-logo.png" alt="Dr. Natasha LEADS"></a><button class="menu" onclick="toggleMenu()" aria-label="Open menu">☰</button><nav class="links">{links}<a class="btn" href="speaker.html">BOOK DR. NATASHA</a></nav></div></header>'''

def footer():
    links = ' | '.join(f'<a href="{href}">{label}</a>' for label, href in NAV[1:])
